<?php $c=$category??[];$action=$category?'/admin/categorii/'.$c['id'].'/salvare':'/admin/categorii/salvare';?><div class="admin-page-head"><div><a class="back-link" href="/admin/categorii">← Categorii</a><h1><?=$category?'Editează categoria':'Categorie nouă'?></h1></div></div><form class="admin-editor simple" action="<?=$action?>" method="post" enctype="multipart/form-data"><?=csrf_field()?><section class="admin-card"><label>Nume<input name="name" value="<?=e($c['name']??'')?>" required></label><div class="admin-form-grid"><label>Slug<input name="slug" value="<?=e($c['slug']??'')?>"></label><label>Categorie părinte<select name="parent_id"><option value="">Fără părinte</option><?php foreach($parents as $parent):if(($c['id']??0)==$parent['id'])continue;?><option value="<?=$parent['id']?>" <?=($c['parent_id']??0)==$parent['id']?'selected':''?>><?=e($parent['name'])?></option><?php endforeach?></select></label></div><label>Descriere scurtă<textarea name="short_description" rows="3"><?=e($c['short_description']??'')?></textarea></label><label>Descriere<textarea name="description" rows="8"><?=e($c['description']??'')?></textarea></label><label>Imagine categorie<input type="file" name="image" accept="image/*"></label><?php if(!empty($c['image_path'])):?><img class="category-preview" src="<?=e(upload_url($c['image_path']))?>" alt=""><?php endif?></section><aside class="editor-side"><div class="admin-card"><label>Status<select name="status"><option value="active">Activă</option><option value="inactive" <?=($c['status']??'')==='inactive'?'selected':''?>>Inactivă</option></select></label><label class="switch-row compact"><span><strong>Afișează pe homepage</strong></span><input type="checkbox" name="show_on_homepage" value="1" <?=!empty($c['show_on_homepage'])?'checked':''?> role="switch"><i></i></label><label>Ordine homepage<input type="number" name="homepage_order" value="<?=e($c['homepage_order']??0)?>"></label><label>Meta title<input name="meta_title" value="<?=e($c['meta_title']??'')?>"></label><label>Meta description<textarea name="meta_description" rows="3"><?=e($c['meta_description']??'')?></textarea></label><label class="switch-row compact"><span><strong>Indexare</strong></span><input type="checkbox" name="indexable" value="1" <?=!isset($c['indexable'])||$c['indexable']?'checked':''?> role="switch"><i></i></label><button class="admin-button wide">Salvează categoria</button></div><?php if($category):?><div class="admin-card danger"><h3>Șterge categoria</h3><p>Ștergerea este permisă numai dacă nu mai are produse atribuite.</p><button class="admin-button danger wide" type="submit" formaction="/admin/categorii/<?=$c['id']?>/stergere" onclick="return confirm('Sigur ștergi categoria?')">Șterge categoria</button></div><?php endif?></aside></form>
